#!/usr/bin/env python3
"""Join explicit analyst interpretation to the immutable cleaned record IDs.

Manual labels below are analytic judgments, not verified customer identities.
"""
import argparse, csv, json, pathlib, collections
XCASES = [('SX01', '1988319241666441699', 'P2/P3', 'self-reported used Toyota owner and restoration expenditure', 'Restore-and-retain competes with replacement, not merely another oil-change outlet', 'The writer reports buying a 2010 used Toyota for Rp100m and spending Rp25m on Auto2000 suspension work plus an audio upgrade. The entire Rp25m must not be attributed to an Auto2000 invoice. The advice compares this route with buying a younger used car around Rp120m.', 'Offer diagnosis-led staged restoration against retain/repair/replace alternatives. Keep the revenue model job-specific; avoid counting a retained old car as an immediate xEV conversion.', 'Partial reply; parent missing; car model colloquial; no invoice, date of job, exact job cost or retention outcome verified.'), ('SX02', '2003711716526563346', 'P1', 'self-reported prospective customer complaint', 'A working test-drive form cannot substitute for a confirmed demonstrator', 'The writer says they want to buy but cannot find a test-drive unit at Auto2000. The model and geography are unspecified.', 'Track request, model-matched demonstrator confirmation, attendance and completed purchase separately. Assign an accountable branch to confirm a usable unit.', 'One account cannot establish network-wide stock absence, xEV model or lost sale.'), ('SX03', '2034986684908281886', 'P2', 'workshop-selection advice', 'Competence is selected by job, not by one global trust score', 'The writer separates routine service, body repair, parts specialists and brand specialists, and reads low ratings in context rather than treating every complaint as workshop fault.', 'Build the competitive set and routing by exact work scope. Keep complex diagnosis separate from a one-visit routine-job promise.', 'Advice is not an observed job or measured choice share.'), ('SX04', '1899585834845962351', 'P2/P1', 'self-reported community-mediated assistance', 'A community can already own the breakdown handoff', 'The writer says they joined a community before buying, then received workshop pickup through the group after a head-gasket problem during a homeward trip.', 'Compete for accountable fulfillment, or partner with an existing community referral path; do not assume discovery is unserved because it is outside Digiroom.', 'Reply with supplied parent; workshop/brand/job outcome and payment not identified.'), ('SX05', '2067793260903645526', 'P1', 'self-reported stated vehicle-choice constraint', 'Single-car resilience is a distinct objection from technology enthusiasm', 'The writer praises competing technology but says they can maintain only one car and therefore still prefer a Japanese option.', 'Use a household-specific demonstration covering routine, long-trip and fallback needs; compare a sole-car household separately from adding a second car.', "The precise competitor/model and completed purchase are not established; feature descriptions are the writer's claims."), ('SX06', '2068876979131355331', 'P1/P3', 'self-reported EV transition, opening thread post', 'Retaining old-car repair costs and Jakarta access can trigger replacement before resale certainty', 'The author attributes an EV switch to odd-even restrictions and a previous car over five years old with rising repair needs, then introduces a personal plan to replace uncertain future resale value.', 'Model reasons to replace by household/job context. Do not collapse all xEV acquisition into environmental education or guaranteed resale.', 'Same author/thread as SX07, not independent evidence; intervening thread posts remain missing; no verified vehicle or transaction.'), ('SX07', '2068881419091542064', 'P3', 'self-reported saving strategy, partial thread continuation', 'A customer may self-fund a future resale buffer instead of purchasing a guarantee', 'The author says savings are visible after six months and considers putting them into a less liquid product for around five years.', 'Show configurable retain/replace scenarios and net upgrade cash. Test executable appraisal/settlement before designing an expensive universal residual-value promise.', 'Partial thread; saving amounts, investment returns, price outcomes and event dates not supplied. Root SX06 recovered in broader collection; immediate parent remains absent.'), ('SX08', '2097968572232609912', 'P2', 'publisher-reported customer allegation', 'A recall-related return visit is a service-recovery issue, not a paid-job sales lead', 'MediaKonsumen reports an Altis owner alleging a power-window malfunction after a Pasar Kemis recall visit and dissatisfaction with the explanation.', 'Separate recall/warranty recovery from paid acquisition funnels. Require documented diagnosis and case closure before suggesting paid upsell.', 'Third-party allegation, not adjudicated misconduct or independently verified cause; no source body beyond post verified.'), ('SX09', '1969347534247071968', 'P2', 'household hearsay and competitor comparison', 'Official-service trust is contested by a specific credible local alternative', 'Writer reports a spouse using Shell Soepomo and praises its result and honesty in comparison with Auto2000.', 'Compare job-matched local alternatives, communication and scope authorization; avoid treating all independents as untrusted or technically inferior.', 'Partial reply and household hearsay; job, invoice and objective quality unknown.'), ('SX10', '2068240559026954670', 'P1/P2', 'self-reported other-brand ownership, adjacent case', 'A satisfied used-ICE purchase can defer EV conversion for several years', 'Writer reports a used Nissan X-Trail chosen for family space, comfort and budget, while accepting fuel/maintenance costs and contemplating EV in three to five years.', 'Maintain a paid-care relationship and an explicit replacement horizon instead of interpreting all EV interest as immediate qualified demand.', 'Other-brand adjacent evidence; not Toyota/Auto2000 transaction, and future intention is not a conversion forecast.')]
YTCASES = {'UgzHqp507BS99rKy69d4AaABAg': ('self_reported_M6_repair', 'A concrete positive aftersales episode names a remedy and outcome: window-rubber noise reportedly ceased after treatment at Harmoni Slipi.', 'Route the reported symptom to a case owner with a remedy and closure record; a branch count alone cannot express service competence.'), 'UgxCY9rAOypo_Qc9iRZ4AaABAg': ('self_reported_EV_charging_cost_strategy', 'Writer says they use an EV without installing a supplied wall charger because a separate meter would cost about Rp6m, and instead charge publicly every two weeks.', 'Demonstrate the household installation-inclusive route and cash requirement. Treat the stated figure as an account, not a current PLN quote.'), 'UgxRfRERl5YxHfDQRmp4AaABAg': ('self_reported_purchase_and_supply_belief', "Writer says they chose Atto1 and cites the producer's local factory commitment as a signal of parts supply and continuity.", 'Address continuity through enforceable support and case ownership; do not dismiss all resale discussion as irrational battery fear. Factory-progress claims remain unverified source beliefs.'), 'Ugxhpwx85X4Cn7LzmTt4AaABAg': ('general_aftersales_complaint', 'Writer alleges BYD aftersales shifts risks to owners, without a named episode, invoice or remedy.', 'Retain as an allegation and question for detailed inquiry, never as a verified defect rate.'), 'UgxDyU5itR1nPBIx2u94AaABAg': ('general_sales_complaint', 'Writer complains about sales promises and communication without identifying a specific transaction.', 'Test a traceable promise-to-fulfillment handoff, while preserving the distinction from verified owner experience.'), 'Ugx1gHnDHm3utVgTu-F4AaABAg': ('rival_explanation_for_resale_discourse', 'Writer argues the Neta situation concerns dealer closure rather than electric propulsion in general.', 'Separate brand continuity, support availability and vehicle condition when assessing resale concerns. This is an explanation offered in discourse, not verified Neta economics.'), 'UgyXIT_9H0GbQHIhpzl4AaABAg': ('technical_claim_not_verified', 'Writer asserts public fast charging affects battery life and links to another video.', 'Do not treat comment assertions as technical evidence or prescribe charging practice from this source.'), 'UgyR_0kEx2h68i04KGl4AaABAg': ('channel_owner_promotion', 'Creator advertises used-car financing.', 'Exclude creator promotion from independent owner evidence.')}

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--social-dir', type=pathlib.Path, default=pathlib.Path('.'))
    ap.add_argument('--pilot-cases', type=pathlib.Path)
    a = ap.parse_args()
    p = a.social_dir
    corp = {platform: {r['record_id']: r for r in map(json.loads, open(p / 'cleaned' / f'{platform}.jsonl', encoding='utf-8'))} for platform in ['x', 'youtube']}
    evidence = []
    for eid, ident, prong, role, headline, interpretation, decision, scope in XCASES:
        r = corp['x'][ident]
        evidence.append({'evidence_id': eid, 'platform': 'x', 'record_id': ident, 'prong': prong, 'analyst_role': role, 'headline': headline, 'interpretation': interpretation, 'decision': decision, 'scope': scope, 'quote_original': r['text_normalized'], 'source_files': r['source_files'], 'source_url': r['source_url'], 'parent_in_corpus': r['parent_in_corpus'], 'root_in_corpus': r['root_in_corpus'], 'verified_transaction': False})
    if a.pilot_cases:
        for old in json.loads(a.pilot_cases.read_text(encoding='utf-8')):
            r = corp['x'][old['post_id']]
            evidence.append({'evidence_id': 'PILOT_' + old['case_id'], 'platform': 'x', 'record_id': old['post_id'], 'prong': old['prong'], 'analyst_role': old['evidence_type'], 'headline': old['finding'], 'interpretation': old['evidence_paraphrase'], 'decision': old['test_implication'], 'scope': old['limitation'] + ' This field preserves the pilot interpretation; consult current parent/root coverage fields for the merged corpus.', 'quote_original': r['text_normalized'], 'source_files': r['source_files'], 'source_url': r['source_url'], 'parent_in_corpus': r['parent_in_corpus'], 'root_in_corpus': r['root_in_corpus'], 'verified_transaction': False})
    ytannotations = []
    for ident, r in corp['youtube'].items():
        role, note, decision = YTCASES.get(ident, ('channel_owner_reply' if r['author_is_channel_owner'] else 'discourse_or_non_specific_comment', 'No detailed independent ownership or completed-job episode established from this comment alone.', 'Use as selected discourse context; not an owner/outcome denominator.'))
        ytannotations.append({'record_id': ident, 'video_id': r['video_id'], 'comment_type': r['comment_type'], 'analyst_role': role, 'analyst_note': note, 'decision_implication': decision, 'verified_owner_or_transaction': False, 'text_original': r['text_original']})
        if ident in YTCASES:
            evidence.append({'evidence_id': 'SY' + str(list(YTCASES).index(ident) + 1).zfill(2), 'platform': 'youtube', 'record_id': ident, 'prong': 'P1/P2/P3', 'analyst_role': role, 'headline': note, 'interpretation': note, 'decision': decision, 'scope': 'Selected comments, no exact publication date, verified owner identity, invoice, transaction or population inference.', 'quote_original': r['text_normalized'], 'source_files': r['source_files'], 'source_url': r['video_url'] + '&lc=' + ident, 'verified_transaction': False})
    for fname, rs in [('curated_social_evidence.jsonl', evidence), ('youtube_analyst_annotations.jsonl', ytannotations)]:
        with open(p / fname, 'w', encoding='utf-8') as f:
            for r in rs:
                f.write(json.dumps(r, ensure_ascii=False).replace('\u2028', '\\u2028').replace('\u2029', '\\u2029').replace('\x85', '\\u0085') + '\n')
    print(json.dumps({'curated_evidence': len(evidence), 'youtube_annotated': len(ytannotations), 'youtube_roles': dict(collections.Counter((r['analyst_role'] for r in ytannotations)))}, indent=2))
if __name__ == '__main__':
    main()
